-- A sheet's rate for each grade: a percent with two decimals (0.00 or more). A grade has at most
-- one rate; setting it again replaces it. A grade with no row has no rate.
CREATE TABLE rate (
    sheet_id VARCHAR(200)  NOT NULL REFERENCES sheet (id),
    grade    VARCHAR(1)    NOT NULL,
    pct      DECIMAL(7, 2) NOT NULL CHECK (pct >= 0),
    PRIMARY KEY (sheet_id, grade)
);
-- A rate can carry a from-date: a grade may have several rates, each in force from its from-date
-- (a rate with none applies from the beginning of time). A grade has at most one rate per from-date
-- (setting it again replaces it); the store keeps that, as a null from-date cannot be in a key.
ALTER TABLE rate ADD COLUMN from_date DATE;
ALTER TABLE rate DROP PRIMARY KEY;
CREATE INDEX rate_sheet_grade ON rate (sheet_id, grade, from_date);
-- A rate can carry a to-date: it applies through that date (null: with no end). A claim dated after
-- the to-date of the rate that would apply to it (the latest from-date on or before the claim's date)
-- has no rate; an earlier rate does not come back.
ALTER TABLE rate ADD COLUMN to_date DATE;
-- A period's cap on open claims per person: how many OPEN or PENDING claims whose due-by falls in it a
-- person may have; a claim belonging to it is not opened beyond that. NULL for none.
ALTER TABLE period ADD COLUMN claim_cap INT;
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.history.HistoryRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class RateRepository {

    private final JdbcTemplate jdbc;
    private final HistoryRepository history;

    public RateRepository(JdbcTemplate jdbc, HistoryRepository history) {
        this.jdbc = jdbc;
        this.history = history;
    }

    public boolean sheetExists(String sheetId) {
        Integer known = jdbc.queryForObject("SELECT COUNT(*) FROM sheet WHERE id = ?", Integer.class, sheetId);
        return known != null && known > 0;
    }

    /** The sheet's rates, by grade then from-date (an undated rate first). */
    public List<Rate> list(String sheetId) {
        return jdbc.query("SELECT grade, pct, from_date, to_date FROM rate WHERE sheet_id = ?"
                + " ORDER BY grade, from_date NULLS FIRST",
                (rs, i) -> new Rate(rs.getString("grade"), pct(rs.getBigDecimal("pct")),
                        from(rs.getObject("from_date", LocalDate.class)),
                        from(rs.getObject("to_date", LocalDate.class))), sheetId);
    }

    /** Set a grade's rate from a from-date (null: from the beginning of time), replacing the one the
     *  grade had from that date; it applies through its to-date (null: with no end). */
    public Rate set(String sheetId, String grade, BigDecimal pct, LocalDate from, LocalDate to) {
        Date on = from == null ? null : Date.valueOf(from);
        jdbc.update("DELETE FROM rate WHERE sheet_id = ? AND grade = ? AND from_date IS NOT DISTINCT FROM ?",
                sheetId, grade, on);
        jdbc.update("INSERT INTO rate (sheet_id, grade, pct, from_date, to_date) VALUES (?, ?, ?, ?, ?)",
                sheetId, grade, pct, on, to == null ? null : Date.valueOf(to));
        history.rate(sheetId, grade, pct, from, to);
        return new Rate(grade, pct(pct), from(from), from(to));
    }

    /** A from-date as shown (yyyy-mm-dd), or null when there is none. */
    static String from(LocalDate from) {
        return from == null ? null : from.toString();
    }

    /** A percent as shown: two decimals, a dot, no grouping. */
    static String pct(BigDecimal pct) {
        return pct.setScale(2).toPlainString();
    }
}
package net.officefloor.hq.app.rate;

/** A sheet's rate for a grade: a percent with two decimals, in force from its from-date (yyyy-mm-dd;
 *  null when it applies from the beginning of time) through its to-date (null when it has no end). */
public record Rate(String grade, String pct, String from, String to) {
}
package net.officefloor.hq.app.rate;

import java.util.List;

/** A sheet's rates, by grade then from-date (an undated rate first); a grade with no rate is not listed. And
 *  {@code inherited}: the rates of the sheets its grades fall back to, nearest first (its parent, the parent's parent,
 *  up to three levels up), each listed the same way. */
public record Rates(List<Rate> rates, List<List<Rate>> inherited) {
}
package net.officefloor.hq.app.rate;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithRates {
    public void respond(@Val Rates rates, ObjectResponse<Rates> response) {
        response.send(rates);
    }
}
package net.officefloor.hq.app.rate;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.history.AsOfView;
import net.officefloor.hq.app.settings.SettingsRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadRates {
    public void load(@PathVariable("sheetId") String sheetId, ServerHttpConnection connection,
            RateRepository repository, SettingsRepository settings, AsOfView view, Out<Rates> rates)
            throws BadRequestException {
        CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        rates.set(view.read(connection, id, () -> new Rates(repository.list(id),
                settings.rateAncestors(id).stream().map(repository::list).toList())));
    }
}

