package net.officefloor.hq.app.history;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.sql.DataSource;
import org.springframework.beans.factory.InitializingBean;
import org.springframework.context.annotation.DependsOn;
import org.springframework.stereotype.Component;

/** At start-up, once the schema is migrated: puts the {@link RowCapture} trigger on each of a sheet's tables
 *  (every table with a sheet_id, and the sheet itself), and makes the table each is replayed into in the asof
 *  schema (see {@link AsOfView}). A table added later is captured the same way, with no change here. */
@Component
@DependsOn("flywayInitializer")
public class RowCaptureInstaller implements InitializingBean {

    /** The tables that are not a sheet's state: the change log itself, and the history a statement as of a
     *  past date reads (V48__history.sql). */
    private static final Set<String> SKIPPED = Set.of("ROW_CHANGE", "CLAIM_HISTORY", "RATE_HISTORY", "GRADE_HISTORY",
            "SETTING_HISTORY", "POLICY_HISTORY", "RETIRE_HISTORY");

    /** A captured table: its name, its columns in order, the positions of its primary key's columns (empty
     *  when it has none) and of the column holding the sheet's id. */
    public record Table(String name, List<String> columns, List<Integer> key, int sheetColumn) {
    }

    private final DataSource dataSource;
    private final Map<String, Table> tables = new LinkedHashMap<>();

    public RowCaptureInstaller(DataSource dataSource) {
        this.dataSource = dataSource;
    }

    /** The captured tables, by name. */
    public Map<String, Table> tables() {
        return tables;
    }

    @Override
    public void afterPropertiesSet() throws SQLException {
        try (Connection conn = dataSource.getConnection()) {
            List<String> names = new ArrayList<>();
            try (ResultSet rs = conn.createStatement().executeQuery("SELECT TABLE_NAME FROM INFORMATION_SCHEMA.TABLES"
                    + " WHERE TABLE_SCHEMA = 'PUBLIC' AND TABLE_TYPE = 'BASE TABLE' ORDER BY TABLE_NAME")) {
                while (rs.next()) names.add(rs.getString(1));
            }
            boolean baseline = empty(conn);
            for (String name : names) {
                if (SKIPPED.contains(name)) continue;
                List<String> columns = RowCapture.columns(conn, "PUBLIC", name);
                int sheetColumn = columns.indexOf(name.equals("SHEET") ? "ID" : "SHEET_ID");
                if (sheetColumn < 0) continue;
                Table table = new Table(name, columns, key(conn, name, columns), sheetColumn);
                tables.put(name, table);
                try (Statement st = conn.createStatement()) {
                    st.execute("DROP TABLE IF EXISTS ASOF.\"" + name + "\"");
                    st.execute("CREATE TABLE ASOF.\"" + name + "\" AS SELECT * FROM PUBLIC.\"" + name + "\" WITH NO DATA");
                    st.execute("DROP TRIGGER IF EXISTS PUBLIC.\"CAPTURE_" + name + "\"");
                    st.execute("CREATE TRIGGER PUBLIC.\"CAPTURE_" + name + "\" AFTER INSERT, UPDATE, DELETE ON PUBLIC.\""
                            + name + "\" FOR EACH ROW CALL '" + RowCapture.class.getName() + "'");
                }
                if (baseline) baseline(conn, table);
            }
        }
    }

    private static boolean empty(Connection conn) throws SQLException {
        try (ResultSet rs = conn.createStatement().executeQuery("SELECT COUNT(*) FROM PUBLIC.ROW_CHANGE")) {
            return rs.next() && rs.getLong(1) == 0;
        }
    }

import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSingleFlight } from '../../query/useSingleFlight';
import { PersonCells, PersonColumnHead } from '../../slots/defs/personRow';
import { SheetBody } from '../../slots/defs/sheetBody';
import { GRADES } from '../people/usePeople';
import { useSheetToday } from '../today/useSheetToday';
import { useDueTotals, useExcess, useSettledOpenTotals } from './useDueTotals';
import { useRatePreview } from './useRatePreview';
import { rateFor, ratesKey, sumDues, trimmedSum, useRates, type Rate } from './useRates';

/** The sheet's rates for each grade: a form that sets one from an optional from-date (replacing the
 *  grade's rate from that date; blank is from the beginning of time) through an optional to-date
 *  (blank is no end), the rates set, and the rate in
 *  force on the sheet's today for every grade ('n/a' when none is). */
function Rates({ sheetId }: { sheetId: string }) {
  const rates = useRates(sheetId);
  const today = useSheetToday(sheetId);
  const queryClient = useQueryClient();
  const [grade, setGrade] = useState<string>('A');
  const [pct, setPct] = useState('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');

  const submitOnce = useSingleFlight();
  const save = useMutation({
    mutationFn: (f: { grade: string; pct: string; from: string; to: string }) =>
      postJson<Rate>(`/api/sheets/${encodeURIComponent(sheetId)}/rates`, f),
    onSuccess: async () => {
      setPct('');
      setFrom('');
      setTo('');
      await queryClient.invalidateQueries({ queryKey: ratesKey(sheetId) });
    },
  });

  return (
    <section data-testid="rates">
      <form
        data-testid="rate-form"
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            save.reset();
            return save.mutateAsync({ grade, pct, from, to });
          });
        }}
      >
        <label>
          Grade{' '}
          <select
            data-testid="rate-form-grade"
            value={grade}
            onChange={(e) => {
              setGrade(e.target.value);
              save.reset();
            }}
          >
            {GRADES.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
        </label>{' '}
        <label>
          Rate %{' '}
          <input
            data-testid="rate-form-pct"
            inputMode="decimal"
            value={pct}
            onChange={(e) => {
              setPct(e.target.value);
              save.reset();
            }}
          />
        </label>{' '}
        <label>
          From{' '}
          <input
            type="text"
            placeholder="yyyy-mm-dd"
            data-testid="rate-form-from"
            value={from}
            onChange={(e) => {
              setFrom(e.target.value);
              save.reset();
            }}
          />
        </label>{' '}
        <label>
          To{' '}
          <input
            type="text"
            placeholder="yyyy-mm-dd"
            data-testid="rate-form-to"
            value={to}
            onChange={(e) => {
              setTo(e.target.value);
              save.reset();
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="rate-form-submit" disabled={save.isPending}>
          Set rate
        </button>
        {save.isError && <p data-testid="rate-form-error">{save.error.message}</p>}
      </form>
      <table data-testid="rates-list">
        <thead>
          <tr>
            <th>Grade</th>
            <th>Rate %</th>
            <th>From</th>
            <th>To</th>
          </tr>
        </thead>
        <tbody>
          {(rates.data ?? []).filter((r) => r.level === 0).map((r) => (
            <tr key={`${r.grade}-${r.from ?? 'start'}`} data-testid={`rate-row-${r.grade}-${r.from ?? 'start'}`}>
              <td data-testid="rate-grade">{r.grade}</td>
              <td data-testid="rate-pct">{r.pct}</td>
              <td data-testid="rate-from">{r.from ?? ''}</td>
              <td data-testid="rate-to">{r.to ?? ''}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <p>
        Current rates:{' '}
        {GRADES.map((g) => (
          <span key={g}>
            {g} <strong data-testid={`rate-current-${g}`}>{rateFor(rates.data, g, today.data?.today) ?? 'n/a'}</strong>{' '}
          </span>
        ))}
      </p>
      <ImportRates sheetId={sheetId} />
      <RatePreview sheetId={sheetId} />
      {rates.isError && <p data-testid="rates-error">{rates.error.message}</p>}
    </section>
  );
}

/** A rate import box: lines of grade,rate,from,to (the from and to may be absent or blank), each set in
 *  order as the rate form sets it. The server checks every line first: one refused line refuses the import
 *  and sets nothing. Shows how many were set (gone while it runs). */
function ImportRates({ sheetId }: { sheetId: string }) {
  const [text, setText] = useState('');
  const queryClient = useQueryClient();
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { useReader } from '../../api/readNow';

/** A grade's rate: a percent with two decimals, in force from its from-date (yyyy-mm-dd; null when it
 *  applies from the beginning of time) through its to-date (null when it has no end). `level` is the sheet it
 *  is set on: 0 this sheet, 1 its parent, 2 the parent's parent, 3 the one above that. */
export type Rate = { grade: string; pct: string; from: string | null; to: string | null; level?: number };

export function ratesKey(sheetId: string) {
  return ['sheet', sheetId, 'rates'];
}

/** The sheet's rates (level 0), by grade then from-date (an undated rate first); a grade with no rate is not
 *  listed. Then those of the sheets its grades fall back to, nearest first (level 1 its parent, up to 3). */
export function useRates(sheetId: string) {
  const read = useReader();
  return useQuery({
    queryKey: read.key(ratesKey(sheetId)),
    queryFn: async () => {
      const got = await read.get<{ rates: Rate[]; inherited: Rate[][] }>(`/api/sheets/${encodeURIComponent(sheetId)}/rates`);
      return [
        ...got.rates.map((r) => ({ ...r, level: 0 })),
        ...(got.inherited ?? []).flatMap((rates, i) => rates.map((r) => ({ ...r, level: i + 1 }))),
      ];
    },
  });
}

/** The rate (a two-decimal percent) for a grade in force on a date (yyyy-mm-dd): on this sheet, the one with
 *  the latest from-date on or before it, an undated rate applying from the beginning of time, unless the date is
 *  after that rate's to-date; when this sheet has none in force, its parent's the same way, then the parent's
 *  parent's, up to three levels up; undefined when none applies. */
export function rateFor(rates: Rate[] | undefined, grade: string | undefined, on: string | undefined): string | undefined {
  if (on === undefined) return undefined;
  for (let level = 0; level <= 3; level++) {
    let found: Rate | undefined;
    for (const r of rates ?? []) {
      if ((r.level ?? 0) !== level || r.grade !== grade || (r.from !== null && r.from > on)) continue;
      if (found === undefined || (found.from ?? '') < (r.from ?? '')) found = r;

